insert into public.lokal_points (location_id, linked_location_id, kind, name, note, latitude, longitude, sort_order) values
  (3, null, 'practical', 'Hitta hit', 'Utgå från väg 15, 600 m öster om Markaryds kyrka, sväng vänster mot Tannsjö och efter 6 km sväng höger, skyltat Sågverk. Kör förbi brädgården. Efter stenmuren finns en P-plats och en anslagstavla om sjöns fågelliv. Följ den markerade vägen genom gården (gula huset) och vidare genom en björkallé och mossodlingar. Vid vändplanen efter ca 800 m viker du av till vänster och följer stigen ca 1 km till fågeltornet. Stigen är svårframkomlig vid regnväder.', null, null, 10),
  (3, null, 'practical', 'Naturen', 'Sjön tappades i slutet av 1800-talet. I västra delen finns diken och kanaler och i sydvästra delen torvbrytning. Östra delen av myren är ganska orörd.', null, null, 20),
  (3, 114, 'place', 'Fågeltornet', 'Vy över sjön från tornet.', 56.531885, 13.643024, 30),
  (11, null, 'practical', 'Parkeringsplats', 'Parkera här vid besök på Skogön och Borgön.', 56.4949, 13.507969, 10),
