  (102, null, 'place', 'Västra våtmarken', 'Säker plats för vattenrall året om, och förmodligen en av de bästa platserna i länet. Ibland kan minst tre individer höras samtidigt. Småfläckig sumphöna, kärrsångare och härmsångare har också hörts här, och vid ett tillfälle sågs ägretthäger. Ett tranpar ses regelbundet, och även brun kärrhök.', 56.4750663, 13.5791013, 10),
  (102, null, 'place', 'Rondelldammen', 'Här har bland annat årta och stjärtand rastat. År 2018 upptäcktes en svarthakad buskskvätta. Vid lågt vattenstånd brukar skogssnäppan födosöka. Kungsfiskare har setts vid ett par tillfällen.', 56.4739697, 13.5813228, 20),
  (102, null, 'place', 'Trastdammen', 'Här sjöng trastsångare och vassångare 2021, båda nya arter för Markaryds kommun. Rosenfink har hörts i området 2010 och 2020.', 56.4729776, 13.5822723, 30),
  (102, null, 'place', 'Krickdammen', 'Här häckar sothöna och rörhöna. Även grönbena har setts. Sädesärlor födosöker ofta i dammen.', 56.4730002, 13.5816551, 40),
  (102, null, 'place', 'Knipdammen', 'Oftast ligger här några knipor och gräsänder, och forsärlan brukar födosöka längs dammkanterna.', 56.4732145, 13.5811193, 50),
  (102, 125, 'place', 'Rallvägen', 'En bra obsplats för att både höra och se vattenrall. Vintertid oftast också bra för varfågel, gärdsmyg och kungsfågel, och sommartid för törnskata.', 56.4745689, 13.580273, 60),
  (102, 134, 'place', 'Trösklen', 'Vintertid bra lokal för strömstare. Utter har också setts. Under vår och sommar forsärla. Kungsfiskare kan ses sällsynt hela året.', 56.4756376, 13.5769866, 70),
  (102, null, 'place', 'Alkärret', 'Mindre hackspett kan sällsynt höras här.', 56.4762149, 13.5801862, 80),
  (102, null, 'place', 'Grusschaktet', 'Häckplats för backsvala.', 56.4742432, 13.5832729, 90),
  (102, null, 'place', 'Svetsareplanen', 'Häckplats för mindre strandpipare.', 56.4750404, 13.5862196, 100),
  (102, 120, 'place', 'Sjöstrands ängar', 'Vissa år översvämmas ängarna. Den stora eken är ett mäktigt inslag i området.', 56.4804169, 13.5910962, 110),
  (102, null, 'place', 'Alskogen', 'På våren växer här rikligt med vitsippor.', 56.475993, 13.5766933, 120),
